out=Path('docs/research/frame-pass3');base=json.loads(Path('docs/research/expansion/yamaha/workshop-pass2/airbox-remove-refit-v1.procedure.json').read_text());url=base['source']['source_url']
def step(id,title,text,pages,check,record=False,diagram=False):return dict(id=id,title=title,instruction=text,source_pdf_pages=pages,verification=[check],record_required=record,diagram_reference_required=diagram,source_links=[url+f'#page={n}' for n in pages] if diagram else [],origin='Original OEM-based summary; record prompts and sealed-assembly handling are explicit workshop workflow adaptations.')
def emit(name,title,scope,steps,exclusions,tools,parts=[],dependencies=[]):
 p={k:copy.deepcopy(base[k]) for k in ['schema_version','target','scope_confirmed','status','publication_status','source']};p.update(id='yamaha-2026-yz450f-'+name,title=title,completeness=scope,applicability={'included':'Exact stock 2026 US standard YZ450F; original serviceable assemblies unless explicitly replaced below','excluded':['Other years/models and non-stock assemblies','Frame repair/welding/straightening']+exclusions},prerequisites=['Match the exact bike and installed stock parts. Have the complete cited diagrams available.','Stable maintenance stand and support suitable for changing weight distribution; clean labeled parts storage.'],required_tools=[{'name':x,'spec':None} for x in tools],required_parts=parts,critical_stop_conditions=['Unstable support, bent/cracked parts, damaged fasteners or unknown assembly order.','Binding, leaks, missing hardware or abnormal brake/control function remains an unresolved fault.'],steps=steps,operation_dependencies=dependencies)
 for i,s in enumerate(steps):s['depends_on']=[steps[i-1]['id']] if i else []
 p['source']['pdf_pages']=sorted(set(n for s in steps for n in s['source_pdf_pages']));p['source']['printed_pages']=['See exact PDF page links at each step'];p['source']['review_note']='Text and assembly diagrams visually checked for this bounded operation; no generalization to other years or modified parts.'
 path=out/(name+'.procedure.json');path.write_text(json.dumps(p,indent=2,ensure_ascii=False)+'\n',encoding='utf-8');return p
front=[
 step('prepare','Support the front of the bike','Secure the bike on a maintenance stand with the front wheel clear of the ground. Keep the complete brake system closed. Prevent the front brake lever being operated while the disc is absent.',[129,131],'Stable support and brake control protected.'),
 step('remove','Remove the wheel and retain both collars','Loosen all four front axle pinch bolts. Support the wheel, remove its axle nut and withdraw the axle, then lower the wheel clear of the caliper. Label the left and right collars separately and keep dirt off the seals and disc.',[129],'Axle, nut and side-specific collars accounted for; brake hose untouched.',False,True),
 step('inspect','Inspect the removed wheel','Check the axle for bending by rolling it on a flat surface; replace a bent axle rather than straightening it. Inspect the wheel, tire, collars and seals for damage and the bearings for roughness or looseness. Record defects; bearing, tire or disc repair is a separate operation.',[131],'Axle straight; wheel/collars/seals serviceable; bearings smooth without looseness.',True),
 step('refit','Fit collars, wheel and axle','Apply lithium-soap-based grease to the axle and oil-seal lips. Replace the collars on their original sides. Lift the wheel with its disc correctly between the pads and insert the axle. Thread on the axle nut without final tightening.',[129,132],'Collars seated; disc between pads; greased axle inserted.',False,True),
 step('seat','Seat the fork before tightening','With the bike securely supported on its wheels, push down on the handlebars several times and check smooth fork rebound before tightening the front axle nut. This is a stationary seating operation; do not ride with loose axle hardware.',[133],'Fork compressed and rebounds smoothly before final torque.'),
 step('torque','Secure the axle hardware','Tighten the front axle nut to 115 N·m, then tighten all four axle pinch bolts to 21 N·m.',[133],'Axle nut115 N·m; four pinch bolts21 N·m.'),
 step('close','Verify the wheel and brake','Check wheel rotation, normal firm front-brake operation and smooth fork movement. Confirm the collars and all axle hardware are secure. Record completion or unresolved faults; this is wheel removal/refit, not brake or bearing service.',[90,113,129,133],'Wheel retained correctly; firm normal brake; smooth fork; findings recorded.',True)
];emit('front-wheel-remove-refit-v1','Remove and refit the stock front wheel','Complete wheel removal, intact-assembly inspection, collar/axle refit, seating and torque closure. Brake hydraulic joints, disc and bearings remain assembled.',front,['Brake hydraulic service','Wheel bearing/disc/tire replacement'],['Maintenance stand and stable lowering support','Appropriate axle tools and calibrated torque wrench covering21–115 N·m','Lithium-soap-based grease and clean cloths'])
rear=[
 step('prepare','Support the rear wheel','Support the bike with its rear wheel off the ground. Select neutral. Protect the rear brake pedal against operation while the wheel is removed; keep the hydraulic line closed.',[134,136,111],'Rear wheel clear, bike stable, brake pedal protected.'),
 step('remove','Release the axle and chain','Remove the axle nut. Loosen both adjuster locknuts and turn the adjusting bolts inward to let the wheel move forward. Support the wheel, withdraw the axle and retain both pullers and collars by side. Push the wheel forward, lift the chain from the sprocket and remove the wheel without disturbing the hydraulic line.',[134,136],'Wheel clear; left/right pullers and collars labeled.',False,True),
 step('inspect','Inspect wheel, axle and collars','Check the axle for bending, the tire/wheel and collars for damage, and bearings for roughness or looseness. Inspect seals and sprocket teeth. Record defects; damaged components need the matching repair before refitting.',[131,136],'Serviceability recorded; no damaged parts silently reused.',True),
 step('refit','Refit the wheel and chain','Grease the oil-seal lips with lithium-soap-based grease and refit the collars. Place the disc between the brake pads and locate the caliper bracket correctly in its swingarm guide. Push the wheel forward and put the chain onto the sprocket. Fit the left puller and insert the greased axle from the left.',[134,137,138],'Collars retained; bracket engaged; disc between pads; chain on sprocket; axle from left.',False,True),
 step('hardware','Fit the right puller and nut','Fit the right chain puller, washer and axle nut. Leave the nut temporarily snug until chain adjustment is complete.',[138],'Right puller and washer present; axle nut temporary only.',False,True),
 step('slack','Measure and adjust chain slack','With the rear wheel raised and gearbox in neutral, pull the chain upward above the chain-guide mounting bolt with about50 N. Measure between the drive-chain guide and the bottom of the chain at the exact diagram location. Adjust both sides equally to50–60 mm. Push the wheel forward so each puller/end plate is seated against the swingarm end.',[111,138],'Measured slack50–60 mm using OEM50 N reference; pullers equally adjusted and seated.',True,True),
 step('torque','Secure the rear axle and adjusters','Tighten the rear axle nut to135 N·m and both chain-adjuster locknuts to21 N·m. Recheck the chain slack after tightening.',[112,138],'Axle135 N·m; locknuts21 N·m; final slack recorded.',True),
 step('close','Check chain alignment and brake function','Turn the wheel and check the chain follows the sprockets, the brake disc sits correctly and the rear brake has normal firm operation. Record wheel installation and any unresolved fault before use.',[90,136,137,138],'Alignment, wheel rotation and brake action verified.',True)
];emit('rear-wheel-remove-refit-v1','Remove and refit the stock rear wheel','Complete rear-wheel removal/refit with closed brake hydraulics, exact axle orientation, chain measurement/adjustment and brake closure.',rear,['Brake hydraulic service','Chain replacement','Bearing/disc/sprocket/tire replacement'],['Maintenance stand','Axle and adjuster tools; calibrated torque wrench covering21–135 N·m','Ruler and means to apply approximately50 N for chain measurement','Lithium-soap-based grease'])
