steer.extend([
 step('bar-off','Support the intact handlebar assembly','Mark the existing bar position. Remove the handlebar protector and the four upper-holder bolts, then lift the bar from its holders and support it without loading the cables or hydraulic hoses. Keep controls and grips attached; do not loosen the lower-holder nuts or disconnect hoses/cables for this bounded operation.',[161,162,163],'Bar position recorded; complete bar supported with cables/hoses unstressed.',True),
 step('fender-off','Remove the front fender','Remove its four bolts and retain the mounting hardware in order. Remove the steering-stem nut and lift away the upper bracket and its washer.',[180,181],'Fender, upper bracket and washer retained; all supported.',False,True),
 step('stem-out','Lower the steering stem','Hold the lower bracket so it cannot drop. Use steering nut wrench90890-01403 / YU-A9472 to remove the ring nut. Lower the stem and retain the race cover and upper bearing. Leave serviceable pressed bearing races and the lower bearing installed; pressing replacements is outside this guide.',[181,182],'Lower bracket supported and removed; bearing stack retained in order.',False,True),
 step('steering-inspect','Clean and inspect the steering bearings','Clean the bearings and races with kerosene. Check for pitting/damage and inspect upper/lower brackets and stem for bends, cracks or damage. Record findings. If replacement is needed, stop this reuse-only sequence; bearings and races must be replaced as a set using the separate repair procedure.',[182],'Both bearings/races and brackets inspected; reuse is justified or repair remains open.',True),
 step('steering-grease','Lubricate the bearing stack','Apply lithium-soap-based grease to the bearings, dust-seal/race-cover lips, steering-stem threads and the stem portion shown in the OEM illustration. Return the lower bracket, upper bearing and race cover in the illustrated order. Fit the ring nut with its stepped side downward.',[182,183],'Lubricated bearing/cover stack correct; ring-nut step faces down.',False,True),
 step('preload','Set the steering preload','Hold the torque wrench at a right angle to the steering-nut wrench. Tighten the ring nut initially to38 N·m and turn the steering left/right several times. If it binds, inspect the bearings. Loosen the ring nut one full turn, then retighten to7 N·m. Check full lock-to-lock movement without play or binding.',[63,112,183],'Initial38 N·m, loosen one turn, final7 N·m; smooth steering without looseness.',True,True),
 step('upper-refit','Restore the upper bracket and stem nut','Install the washer and upper bracket. Slide the fork legs into place and temporarily secure the lower clamps, leaving the upper pinch bolts loose. Grease the steering-stem nut contact surface with lithium-soap grease and tighten the stem nut to145 N·m. Check steering again; if movement is not smooth, follow the manual ring-nut adjustment rather than proceeding.',[183,184],'Washer fitted; stem nut145 N·m; steering smooth.',False,True),
 copy.deepcopy(fs['legs-refit']),copy.deepcopy(fs['height-clamps']),
 step('bar-refit','Restore the handlebar and fender','Refit the front fender with its four bolts at10 N·m. Refit the handlebar at its recorded marks with upper-holder punch marks forward and equal side-to-side marks. Tighten the front upper-holder bolts first, then the rear bolts, to28 N·m. Keep the lower holders unchanged. Turn lock-to-lock to confirm no fuel-tank contact or cable/hose tension.',[163,164,180],'Fender10 N·m; holders28 N·m front first; original bar position and free movement.',True,True),
 copy.deepcopy(fs['guards-brake']),copy.deepcopy(fs['wheel-refit']),copy.deepcopy(fs['seat-torque']),copy.deepcopy(fs['plate-settings']),
 step('steering-close','Verify steering and front-end closure','With the front raised, rock the lower fork legs to check for steering play, then sweep lock-to-lock for binding. Check fork movement, wheel rotation, normal firm front-brake operation and hose/cable clearance. Record final checks, fork projection and hardware torques. Do not close an unresolved bearing, brake or control fault.',[90,112,113,184],'No play/binding; fork and brake normal; cable/hose clearance and final readings recorded.',True)
])
