emit('steering-bearing-inspection-v1','Inspect and grease the stock steering bearings','Complete front-end access, lower-bracket removal, inspection/re-greasing of serviceable original steering bearings, preload, and front-end closure. Pressed bearing/race replacement is excluded; controls and closed hydraulics remain attached to the supported handlebar.',steer,['Pressed steering bearing/race replacement','Hydraulic brake/clutch service','Control/grip/cable removal','Aftermarket offset clamps or nonstandard fork projection'],['Maintenance stand and independent bar/caliper/lower-bracket supports','Steering nut wrench90890-01403 / YU-A9472 and calibrated torque wrench at right angle','Cap ring wrench matching stock fork per source; axle/clamp tools','Calibrated torque tools covering7–145 N·m','Lithium-soap-based grease, kerosene and clean parts storage'],dependencies=[{'artifact':str(forkpath),'sha256':hashlib.sha256(forkpath.read_bytes()).hexdigest(),'kind':'inlined_reviewed_access_and_closure','reused_step_ids':['setup','plate','wheel-remove','caliper','protectors','legs-remove','bench-check','legs-refit','height-clamps','guards-brake','wheel-refit','seat-torque','plate-settings']}])
