swing=[copy.deepcopy(s) for s in rear[:3]]
swing.extend([
 step('chain-open','Open the original clip-type drive chain','Remove the master-link clip, plate and master link, then remove the chain. Keep its orientation and original matched parts identified. This operation applies to the stock clip-type joint; a riveted or replacement chain requires its maker\'s joint procedure.',[196,197],'Stock clip joint identified; chain removed; new correct clip ready.',False,True),
 step('brake-clear','Support the closed rear brake assembly','Slide the complete rear caliper and bracket free of the swingarm guide after wheel removal. Release the hose retaining clamps shown in the routing diagram and support the assembly without twisting or stretching the hose. Do not remove hose unions, pads or sliding pins. Remove the brake-pedal pivot bolt and unhook its spring to clear pivot access; support the pedal while leaving its master-cylinder linkage attached.',[76,77,134,150,192,210],'Hose free of swingarm and supported; hydraulics closed; pedal/return spring retained.',False,True),
 step('shock-lower','Unlink the shock and linkage','Support the swingarm independently. Remove the lower shock bolt and keep the shock supported on its unchanged upper mount. Remove the connecting-arm frame bolt, connecting-arm-to-relay bolt and relay-to-swingarm bolt, keeping each fastener and collar/washer stack associated with its joint. Keep the linkage bearings and seals assembled in this inspection-only operation.',[187,188,190,191],'Swingarm cannot drop; three linkage joints and lower shock joint identified.',False,True),
 step('pivot-out','Withdraw the pivot and swingarm','Support the engine and frame while leaving all other engine mounts undisturbed. Remove the pivot nut, withdraw the pivot shaft and lower the supported swingarm. Keep the collars and thrust-bearing/seal stack in their original positions. The pivot also passes through the engine rear mount; do not let engine or swingarm weight bind the shaft.',[194,195,210,211],'Engine and arm independently supported; pivot and bearing stacks labeled.',False,True),
 step('arm-inspect','Inspect the arm, pivot and linkage','Inspect the swingarm for bends/cracks, roll the pivot on a flat surface to detect bending, and inspect the linkage arms, collars, seals and exposed bearing surfaces for wear, pitting or damage. Record free play, rust, binding or damage. Do not straighten a bent pivot. Damaged bearings/bushings or bearings/collars require their stated matched-set replacement, outside this intact-bearing guide.',[189,194],'Serviceability recorded for pivot, arm and every linkage joint.',True),
 step('grease-arm','Grease and position the swingarm','Apply molybdenum-disulfide grease to the pivot, bearing contact surfaces, thrust bearings, bushings, collars and seals per the diagram. Return the original intact bearing stacks and arm. Insert the pivot from the right. Apply lithium-soap grease to the pivot-nut threads and contact face and tighten the pivot nut to75 N·m.',[194,195,211,212],'Correct grease locations; original stack order; pivot from right; nut75 N·m.',False,True),
 step('link-refit','Refit the linkage in its original orientation','Lubricate the circumferences and threads of the three linkage bolts and lower shock bolt with molybdenum-disulfide grease. Fit the connecting-arm frame bolt from the right; connecting-arm relay bolt, relay-arm swingarm bolt and lower shock bolt from the left. Restore every retained collar and washer in its original joint. Raise the arm to align the lower shock without forcing the bolts.',[187,189,190],'Original linkage orientation and washer stacks restored; bolt directions matched.',False,True),
 step('link-torque','Secure the linkage and lower shock','Tighten the connecting-arm frame nut and connecting-arm relay nut to80 N·m each. Tighten the relay-arm swingarm nut to70 N·m and the lower shock nut to53 N·m. The unchanged upper shock mount is not part of this removal.',[190,191],'Frame80, relay80, swingarm70, lower shock53 N·m recorded.',True),
 step('brake-refit','Restore pedal and hose routing','Refit the pedal with its original spring and grease the pivot contact/seal locations shown with lithium-soap grease. Tighten the pedal pivot bolt to26 N·m. Route the brake hose clear of the spring and suspension without twist; its paint mark faces upward. Fully seat the hose clamps in their bases, engage each lock by at least three notches and face their openings inward. Keep the complete caliper bracket supported for wheel installation.',[61,76,77,210],'Pedal26 N·m; spring restored; hose/retainers matched; no open hydraulics.',False,True),
 step('chain-refit','Reconnect the stock chain','Fit the original matched master link and plate with a new correct master-link clip. Follow the OEM diagram so the closed end of the clip leads in the chain\'s direction of travel. Lubricate the chain. Do not reuse the removed clip or apply this procedure to a different chain joint.',[198],'New matching clip fully seated with closed end leading chain travel.',False,True)
]);swing.extend(copy.deepcopy(rear[3:]));swing.append(step('arm-close','Verify the complete rear assembly','Check rear suspension travel for smooth movement, no side play or binding, brake hose clearance, chain alignment/slack and normal firm rear-brake action. Record all disturbed fasteners and any defect. Wheel refit alone does not verify the linkage; record this separate check.',[90,111,138,194,195],'Suspension, chain and brake checks recorded; no unresolved defect hidden.',True))
emit('swingarm-linkage-remove-refit-v1','Remove and refit the stock swingarm and linkage','Complete removal/refit of stock swingarm and intact linkage with rear wheel/chain access and closed rear-brake hydraulics. Existing pressed bearings/seals are inspected in place; shock stays sealed on its upper mount. Engine remains installed on its other mounts and independently supported.',swing,['Pressed bearing/seal replacement','Shock rebuild or upper mount removal','Brake hydraulic service','Engine removal','Riveted or aftermarket chain joints'],['Secure stand plus independent swingarm/engine/caliper support','Torque tools covering21–135 N·m; axle/pivot/linkage tools','Clip-type chain joint tools and approximately50 N chain measurement tool','Molybdenum-disulfide and lithium-soap greases'],parts=[{'name':'New exact stock-chain master-link clip','purpose':'OEM marks the removed joint clip for replacement; verify chain identity first.'}])
print('Saved swingarm/linkage operation')
import re
# An intact hydraulic release unit can be unbolted without opening its hydraulic circuit.
release=[
 step('prepare','Prepare the left-side work area','Stop the engine, let it cool and support the bike. Clean the drive-sprocket/release-cylinder area. Prevent the clutch lever being operated while the release unit is unbolted. Keep the hose unions and bleed screw untouched.',[196,254,261],'Cold supported bike; clean work area; clutch lever protected.'),
 step('cover','Remove the sprocket cover','Remove the two drive-sprocket-cover bolts and the cover, retaining their locations. Do not remove the sprocket or shift pedal for this bounded operation.',[196,254],'Cover and two bolts retained.',False,True),
 step('unit-off','Support and unbolt the release cylinder','Support the intact release-cylinder body, remove its two mounting bolts and ease it away. Keep the hose attached and unstressed; retain the washer and mounting O-ring. Leave push rod2 and its installed oil seal in the engine. Do not operate the lever or allow dirt into the exposed area.',[210,254,257],'Unit supported; hydraulic joints untouched; washer retained; rod and seal undisturbed.',False,True),
 step('inspect','Inspect the mounting interface','Inspect the cylinder body and accessible mounting surfaces for damage and record the condition. A hydraulic leak, damaged cylinder or disturbed piston requires the separate hydraulic service; this guide only removes/refits the intact unit.',[262,263],'Condition recorded; no hydraulic service implied.',True),
 step('seal','Restore the washer and new mounting seal','Fit a new correct release-cylinder mounting O-ring, lubricated with silicone grease. Keep the original washer in the illustrated position. Apply silicone grease to the exposed pushrod-end contact and leave the installed rod oil seal undisturbed. Match the source drawing before seating the cylinder.',[257],'New lubricated O-ring and original washer correctly located; rod seal undisturbed.',False,True),
 step('mount','Secure the intact release cylinder','Seat the cylinder without trapping its O-ring or hose. Apply the source-specified LOCTITE threadlocking treatment to the two mounting bolts and tighten them to10 N·m. The5 N·m bleed screw and30 N·m hose union shown nearby are not mounting bolts and remain untouched.',[59,254,257],'Two mount bolts10 N·m with specified threadlocking treatment; hydraulics closed.',False,True),
 step('cover-refit','Refit the sprocket cover','Replace the cover and tighten both cover bolts to7 N·m. Restore original hose routing and clearances without twist.',[58,65,254],'Cover bolts7 N·m; hose routed without tension or pinch.'),
 step('close','Check clutch operation','Check normal lever operation and inspect for leakage. Record the work as intact cylinder removal/refit. A soft/spongy lever, leak, moving mount or abnormal clutch function is not a completed repair; use the separate source procedure before riding.',[262,263],'Normal clutch operation and no leakage; findings recorded.',True)
]
emit('clutch-release-remove-refit-v1','Remove and refit the intact clutch release cylinder','Complete unbolt/refit of the intact stock release cylinder with its hydraulic hose kept attached, new mounting O-ring and verified closure. Pushrod and shaft oil seal remain installed; no bleeding or clutch-internal overhaul claim.',release,['Opening hydraulic joints or piston service','Pushrod removal or shaft oil-seal replacement','Clutch internal overhaul'],['Stable support for bike and release-cylinder body','Appropriate low-range torque wrench covering7–10 N·m','Silicone grease and source-specified LOCTITE threadlocking treatment'],parts=[{'name':'New exact clutch-release-cylinder mounting O-ring','purpose':'Mounting seal shown new on OEM PDF257; verify OEM part for this exact bike.'}])
