airpath=Path('docs/research/expansion/yamaha/workshop-pass2/airbox-remove-refit-v1.procedure.json');air=json.loads(airpath.read_text());expath=Path('docs/research/expansion/yamaha/workshop-pass2/exhaust-remove-refit-v1.procedure.json');ex=json.loads(expath.read_text());coolpath=Path('docs/research/expansion/yamaha/workshop-pass2/coolant-change-v1.procedure.json');cool=json.loads(coolpath.read_text())
def pick(p,ids,prefix):
 result=[]
 for id in ids:
  x=copy.deepcopy(next(s for s in p['steps'] if s['id']==id));x['id']=prefix+x['id'];result.append(x)
 return result
engine=[step('initial-record','Record the engine and job condition','Record the exact stock engine identity, running condition and reason for removal. Photograph hose, electrical and bracket routing before access. Prepare an independently supported engine bench and a controlled lift with a helper; this guide removes/installs the assembly and does not repair its internals.',[90,91,211],'Engine identity, fault and lift/support plan recorded.',True),
 step('oil-drain','Drain the engine oil before lifting','For a normally running engine, follow the oil-change warm-up then stop the engine; do not run a faulted engine solely to warm oil. Stand the bike upright, place drain containers and remove the filler cap and both oil drain bolts. Drain tank and crankcase. Leave the oil filter unchanged unless separately serviced. Install new drain-bolt gaskets: tank bolt10 N·m, crankcase bolt20 N·m. Mark the engine empty of oil.',[98,99],'Oil drained; two new gaskets; tank10/crankcase20 N·m; engine marked empty.',True,True)]
engine+=pick(air,['prepare','subseat','body'],'access-')
engine+=[step('isolate','Isolate the battery','With the engine stopped, disconnect the negative battery lead first, then the positive lead. Insulate the loose terminals. Retain the battery and relay in place unless separate frame work requires removal; no starter action is allowed during the work.',[123],'Negative then positive disconnected and insulated.',False,True)]
engine+=pick(air,['shrouds','tank-disconnect','tank-remove','case-release','case-remove'],'access-')
engine+=pick(ex,['silencer-remove','midpipe-remove','header-remove'],'exhaust-')
engine+=pick(cool,['prepare','drain','seal'],'cooling-')
engine+=[
 step('coolant-hoses','Disconnect the engine coolant hoses','Identify radiator hoses1,3 and4 from the source drawing. Mark each hose and clamp position, loosen its engine-side clamp and release the hoses from the engine. Keep radiators mounted and protect the open hose/engine ports from dirt. Do not remove coolant pipe joints or the temperature sensor itself.',[210,296,297],'Hoses1/3/4 labeled and clear; pipe joints/sensor remain sealed.',False,True),
 step('intake-clear','Lift the intact throttle body from the engine joint','Clean around the lower intake joint, loosen its clamp and lift the throttle body clear of the engine-side joint. Support the intact body with both throttle cables attached, out of the engine lifting path without tension; protect the open intake. This retained-cable adaptation requires adequate free support clearance. If the cables cannot remain unstressed, stop and use the separate complete cable-removal procedure. Do not disturb sensors, adjustment screws or the throttle pulley.',[57,310,312],'Throttle body supported clear; cables/sensors undisturbed; intake protected.',False,True),
 step('electrical-left','Disconnect the left engine harness interfaces','Release only the retaining clips/ties needed to free engine leads. Disconnect the stator, crankshaft-position and gear-position connectors; keep the gear-position switch bolted to the engine so its seal is not disturbed. Match connector identity to the diagrams, including the white3-pin gear-position and gray2-pin stator connectors. Label and protect both halves.',[64,65,208],'Stator/crank-position/gear-position leads released; sensor seals untouched.',False,True),
 step('electrical-right','Disconnect starter, ground and plug interfaces','Disconnect the coolant-temperature connector, pull the spark-plug cap clear without removing the plug, and remove the engine-ground terminal bolt. At the starter lead, hold the motor-side terminal nut with a spanner while undoing the lead nut. Release the lead clamps and support the harness away from the lift path.',[68,69,72,73,208,222,245],'Ground/starter/temperature/plug disconnected; starter terminal not twisted.',False,True),
 step('sprocket','Remove chain, sprocket and shift pedal','Remove the sprocket cover. Release the stock clip-type chain joint and remove the chain; retain the matched link/plate and prepare a new clip. Remove the sprocket nut and old lock washer using an appropriate holding tool, then remove the sprocket. Mark and remove the shift pedal; retain its bolt and original punch-mark alignment.',[196,197,198,264,267,268],'Chain and sprocket clear; old lock washer/clip retired; shift position recorded.',True,True),
 step('release-cylinder','Unbolt the intact clutch release unit','Protect the clutch lever from operation. Support the release body and remove its two mount bolts while keeping its hydraulic hose attached. Retain the washer, remove the old mounting O-ring and leave push rod2 and its shaft oil seal installed. Support the unit outside the lifting path without stressing the hose.',[210,254,257],'Closed release unit supported; washer retained; new mounting O-ring ready.',False,True),
 step('pedal-guard','Clear pedal, guard and breather','Remove the engine guard, brake-pedal pivot bolt and return spring. Support the pedal with its master-cylinder linkage attached. Label and release the cylinder-head breather hose from the engine and its routing holders. Keep brake hydraulics closed.',[64,65,210],'Guard/pedal/spring retained; breather clear; brake system closed.',False,True),
 step('engine-support','Support engine and swingarm before undoing mounts','Support the engine independently. Support the swingarm and prepare a same-diameter temporary support shaft from its other side if needed when the pivot is withdrawn. Confirm every electrical connector, hose, intake assembly and cable is clear before loosening the engine mounts.',[209,210,211],'Independent supports ready; all engine interfaces clear.',True,True),
 step('mounts-out','Release the engine mounts','Remove the left/right upper brackets and two lower brackets with their identified hardware, keeping bolt positions separate. Withdraw the pivot while maintaining swingarm support. Keep the engine fully supported as the last mounting fasteners come out; never let it hang from a remaining hose or lead.',[209,210,211],'Mount hardware mapped; pivot removed with swingarm supported.',False,True),
 step('engine-out','Lift the engine out to the right','Lift the engine and move its lower part toward the right side of the chassis as shown in the OEM drawing, then transfer it to the prepared support. Stop if any interface catches. Keep the inlet, exhaust and fluid ports protected from contamination.',[211],'Assembly removed to right; no trapped interface; engine stable.',False,True),
 step('bench-record','Record the engine handoff','Record whether the same unopened assembly is returning or a separate documented internal rebuild has been completed. Inspect mounting brackets, bolts and contact surfaces. This guide cannot certify internal timing, bearing clearances or clutch/gearbox assembly; retain that separate job record before installation. For a rebuilt engine, verify its prescribed pre-start clearances, timing and free-rotation checks are complete before engine-in.',[91,211,212],'Engine condition and separate internal-work record identified.',True),
 step('engine-in','Place the engine back in the chassis','Bring the supported engine in from the right and align its mounting points without trapping wires/hoses. Apply molybdenum-disulfide grease to the pivot; install it from the right and restore the swingarm support stack. Apply lithium-soap grease to the pivot-nut threads and contact face.',[195,211,212],'Engine aligned from right; pivot from right; supports and grease correct.',False,True),
 step('mount-torque','Install and secure the engine brackets','Restore the original lower and upper brackets and mapped hardware. Follow the labeled engine-install drawing: pivot nut75 N·m; lower engine-mount bolt53 N·m; front bracket bolts34 N·m; front engine-mount bolt55 N·m; upper bracket bolts34 N·m; upper engine-mount bolts45 N·m. Keep the supported assembly aligned while tightening.',[62,211,212],'All six distinct mounting torque groups recorded against the diagram.',True,True),
 step('release-refit','Restore the clutch release unit','Replace the mounting O-ring and lubricate it and the pushrod contact end with silicone grease. Restore the retained washer and seat the release cylinder. Apply specified LOCTITE treatment to the two mount bolts and torque to10 N·m. Keep hose unions and bleed screw untouched.',[59,254,257],'New O-ring/washer correct; mount bolts10 N·m; hydraulic line closed.',False,True),
 step('pedal-refit','Restore pedal, guard and breather','Restore the brake-pedal pivot and spring, lubricating the illustrated pivot/seal contact locations with lithium-soap grease; tighten its bolt26 N·m. Refit the engine guard at7 N·m. Route the head breather between the two front bracket bolts and rear bracket bolt, with its paint marks within the holder/clamp areas.',[61,62,64,65,210],'Pedal26/guard7 N·m; spring attached; breather routing and marks correct.',False,True),
 step('sprocket-refit','Restore the drive sprocket and chain','Refit the original sprocket with a new lock washer. Apply source-specified LOCTITE to the sprocket nut, tighten it90 N·m and bend the washer tabs against its flats. Align shift-shaft/pedal punch marks and tighten the pedal bolt12 N·m. Refit the cover at7 N·m. Fit the stock chain using its matched link/plate and a new clip with closed end leading chain travel.',[58,59,196,198,267,268],'Sprocket90 and lock tabs; shift12; cover7; new correctly oriented chain clip.',False,True),
 step('ground-starter','Restore the engine ground and starter lead','Refit the ground terminal at the cylinder-head location shown and tighten its bolt7 N·m; point the lead upward and route it outside the high-tension cord. Refit the starter lead at6 N·m while holding the motor-side nut with a spanner. Restore its clamp without slack, as shown.',[64,65,68,69,208,222,245],'Head ground7 N·m and upward; starter6 N·m with terminal counterheld.',False,True),
 step('harness-refit','Reconnect and route the engine harness','Reconnect stator, crankshaft-position, gear-position and coolant-temperature connectors and their covers. Route stator/gear leads outside the head breather; stator lead passes behind the radiator without pinch. Keep clutch hose outside those leads and secure the original lower/upper tie positions shown. Install the plug cap fully against the cover; route ground/temperature/high-tension leads outside the breather. Replace released ties in the diagram directions.',[64,65,68,69,72,73,208],'Every labeled connector latched/covered; source routing and tie locations verified.',False,True),
 step('intake-refit','Reseat the throttle body','Remove intake protection and seat the intact throttle body fully in its original engine-side joint. Restore the clamp orientation and tighten the throttle-body joint clamp to3.0 N·m. Keep both cables routed without tension and check full smooth throttle return. Sensors and calibration screws remain untouched.',[57,96,310,312],'Joint fully seated3.0 N·m; throttle returns smoothly; cables not trapped.',False,True),
 step('hoses-refit','Reconnect the engine coolant hoses','Remove temporary port covers. Restore radiator hoses1,3 and4 to their marked engine connections and original clamp positions; tighten each disturbed radiator-hose clamp screw to1.5 N·m. Check there are no kinks or trapped hoses. Radiator pipe seals and temperature sensor were not removed.',[57,296,297],'Hoses1/3/4 correct; disturbed clamps1.5 N·m.',False,True)
]
