enginep=emit('engine-remove-refit-v1','Remove and refit the stock engine assembly','Complete assembled-bike engine access, removal to the right, bracket/pivot installation, intake/exhaust/cooling/electrical/chain closure and running checks. Engine internals are a separate documented operation. Adaptation keeps throttle cables and hydraulic hoses attached to supported intact units; sufficient unstressed clearance must exist.',engine,['Internal engine teardown/rebuild','Modified intake/routing or insufficient retained-cable clearance','Throttle-cable detachment, sensor calibration or hydraulic opening','Non-stock chain joints'],['Stable chassis and swingarm supports; controlled engine lift and helper','Suitable sprocket holder and clip-chain tools','Torque tools covering1.5–135 N·m including starter terminal counterholding spanner','Oil/coolant catch containers, measuring vessels and fuel-safe transfer equipment','Port covers, labels, replacement retaining ties and protected engine bench','Molybdenum-disulfide, lithium-soap and silicone grease; source-specified LOCTITE'],parts=[{'name':'New engine-oil drain gaskets and filler-cap O-ring','purpose':'Both drains and filler disturbed.'},{'name':'New coolant-drain washer and exact recommended coolant','purpose':'Cooling drain/refill.'},{'name':'New exact clutch-release mounting O-ring','purpose':'Intact release-cylinder mount removed.'},{'name':'New exact sprocket lock washer and stock-chain joint clip','purpose':'OEM one-use locking parts.'},{'name':'New exhaust header/joint seals specified by the inlined exhaust operation','purpose':'Disturbed exhaust interfaces.'},{'name':'Engine oil matched to actual assembly condition','purpose':'Recorded refill and level/flow verification.'}],dependencies=[{'artifact':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'kind':'inlined_reviewed_access_and_closure'} for p in [airpath,expath,coolpath]])
